"${PAGE_CSS}",
"</style>",
"</head>",
"<body>",
"<div class=\"shell\" id=\"shell\" data-view=\"all\">",
"<aside class=\"side\" id=\"side\" aria-label=\"Agent Board\">",
"<div class=\"s-brand\">${boardMark}<span class=\"b-name\">Agent Board</span><span class=\"live\" title=\"${esc2(s.serveLiveHint)}\"><i></i></span><button type=\"button\" class=\"s-toggle\" id=\"side-toggle\" data-local aria-expanded=\"true\" aria-label=\"${esc2(s.pgSideFold)}\" title=\"${esc2(s.pgSideFold)}\"><svg class=\"i\" viewBox=\"0 0 16 16\" aria-hidden=\"true\"><rect x=\"2\" y=\"2.5\" width=\"12\" height=\"11\" rx=\"2\"/><path d=\"M6.5 2.5v11\"/></svg></button></div>",
"<nav class=\"s-group s-views\" id=\"side-views\" aria-label=\"${esc2(s.pgViews)}\">${sideView(\"all\", s.pgOverview, false)}${sideView(\"needs\", s.pgNeeds, true)}${sideView(\"working\", s.pgWorking, true)}${sideView(\"others\", s.pgOthers, true)}${sideView(\"done\", s.pgDone, true)}</nav>",
"<div class=\"s-group s-agents\" id=\"side-agent-group\" role=\"group\" aria-labelledby=\"side-agents-label\" hidden><p class=\"s-label\" id=\"side-agents-label\">${esc2(s.pgAgents)}</p><div class=\"s-group\" id=\"side-agents\"></div></div>",
"<div class=\"s-group s-projects\" id=\"side-project-group\" role=\"group\" aria-labelledby=\"side-projects-label\" hidden><p class=\"s-label\" id=\"side-projects-label\">${esc2(s.pgProjects)}</p><div class=\"s-group\" id=\"side-projects\"></div></div>",
"<div class=\"s-foot\" id=\"side-foot\"></div>",
"</aside>",
"<div class=\"stage\">",
"<header class=\"head\" id=\"head\"><div class=\"col topbar\"><div class=\"brand\">${boardMark}<h1>Agent Board</h1><span class=\"live\" title=\"${esc2(s.serveLiveHint)}\"><i></i><span class=\"lbl\">${esc2(s.serveLive)}</span></span></div></div></header>",
"<div id=\"offline\" role=\"status\" aria-live=\"polite\"></div>",
"<nav class=\"agents\" id=\"agents\" aria-label=\"${esc2(s.pgAgents)}\" hidden><div class=\"col agents-in\" id=\"chips\"></div><div class=\"col agent-note\" id=\"agent-note\"></div></nav>",
"<main class=\"col page\">",
"<div id=\"board\"></div>",
"<details id=\"tidy-bulk\"><summary>${esc2(s.tidyBulk)}</summary><div class=\"fold-in\"><p><label>${esc2(s.tidyBulk)} <select id=\"tidy-kind\"><option value=\"stopped\">${esc2(s.tidyStopped)}</option><option value=\"agent\">${esc2(s.tidyAgent)}</option><option value=\"older\">${esc2(s.tidyOlder)}</option></select> <input id=\"tidy-value\" type=\"text\" inputmode=\"text\" placeholder=\"${esc2(s.tidyValue)}\" aria-label=\"${esc2(s.tidyValue)}\"></label></p><div class=\"acts\"><button type=\"button\" id=\"tidy-preview\" data-local>${esc2(s.tidyPreviewButton)}</button><button type=\"button\" id=\"tidy-confirm\" data-local disabled>${esc2(s.tidyConfirmButton)}</button><button type=\"button\" id=\"tidy-cancel\" data-local disabled>${esc2(s.tidyCancelButton)}</button></div></div></details><footer class=\"pfoot\" id=\"pfoot\"><a class=\"ver-link\" href=\"https://github.com/WenyuChiou/agent-board\" target=\"_blank\" rel=\"noopener\" title=\"${esc2(s.pgGithub)}\"><span id=\"versions\"></span><span aria-hidden=\"true\">·</span>GitHub<svg class=\"i\" viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M6.5 3.5H3.5v9h9v-3M9 3h4v4M13 3 7.5 8.5\"/></svg></a><span class=\"grow\"></span>${isLan ? `<p>${esc2(s.serveLanIdle)}</p>` : idleMs > 0 ? `<p>${esc2(s.serveIdleTimed(idleMs / 60000))}</p>` : \"\"}<span class=\"set-row\">${themeToggle(s)}</span>${isLan ? \"\" : `<button type=\"button\" class=\"btn\" id=\"connect-web-chat\" data-static>${esc2(s.webChatConnect)}</button><button type=\"button\" class=\"btn\" id=\"import-clipboard\" data-static>${esc2(s.importClipboard)}</button>`}<button type=\"button\" id=\"close\" data-static>${esc2(s.serveClose)}</button></footer>",
"<div id=\"note\" role=\"status\" aria-live=\"polite\"></div>",
"</main>",
"</div>",
"</div>",
"${isLan ? \"\" : `<script type=\"application/json\" id=\"relay-prompt\">${JSON.stringify(RELAY_PROMPT).replace(/</g, \"\\\\u003c\")}</script>`}",
"<script type=\"application/json\" id=\"words\">${JSON.stringify(pageWords(isLan ? { ...s, serveOffline: s.serveOfflineLan } : s)).replace(/</g, \"\\\\u003c\")}</script>",
"<script nonce=\"${nonce}\">${PAGE_SCRIPT}</script>",
"</body>",
"</html>",
"`;",
"var PAGE_SCRIPT = String.raw`",
"(function () {",
"  'use strict';",
