"    return parent;",
"  }",
"  function hasClass(node, name) { return (' ' + (node.className || '') + ' ').indexOf(' ' + name + ' ') !== -1; }",
"  function toggleClass(node, name, on) {",
"    var names = String(node.className || '').split(' ').filter(function (one) { return one && one !== name; });",
"    if (on) names.push(name);",
